mapper.update:
UPDATE gpu_device
SET status = 'OFFLINE', updated_at = CURRENT_TIMESTAMP
WHERE cluster_id = #{clusterId}

mapper.select:
SELECT * FROM gpu_device
WHERE cluster_id = #{clusterId}
  AND node_name = #{nodeName}
  AND gpu_index = #{gpuIndex}

SELECT * FROM gpu_device
WHERE cluster_id = #{clusterId}
ORDER BY node_name, gpu_index

SELECT * FROM gpu_device
WHERE node_id = #{nodeId}
ORDER BY gpu_index

SELECT * FROM gpu_device
WHERE resource_pool_id = #{poolId}
ORDER BY cluster_id, node_name, gpu_index

SELECT COUNT(*)
FROM gpu_device
WHERE resource_pool_id = #{poolId}
  AND status = 'READY'
  AND usage_status = 'IDLE'

  AND gpu_model = #{gpuModel}

SELECT gd.cluster_id FROM gpu_device gd JOIN physical_cluster pc ON pc.id = gd.cluster_id WHERE gd.resource_pool_id = #{poolId} AND gd.status = 'READY' AND gd.usage_status = 'IDLE' AND pc.status = 'ACTIVE'
AND gd.gpu_model = #{gpuModel}
GROUP BY gd.cluster_id HAVING COUNT(*) >= #{required} ORDER BY gd.cluster_id
